'use strict';
/* A journal with a visual language for each idea, independent of the homepage. */
C_NAV.splice(2,0,['/composicoes/','Composições','Capacidades em contexto']);
C_NAV.find(x=>x[0]==='/desenvolvedores/')[1]='Desenvolvedores';
C_CORE.find(x=>x[0]==='/desenvolvedores/')[1]='Desenvolvedores';
C_NAV.push(['https://docs.catalisa.app/','Referência de APIs','Contratos e documentação técnica']);
const P_URL='/perspectivas/';
function pWeave(id='weave'){return `<svg class="p-weave" viewBox="0 0 850 640" role="img" aria-label="Fitas de linhas se cruzam e abrem caminhos"><defs><linearGradient id="${id}-ink" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#ab8ac4"/><stop offset=".6" stop-color="#734b9c"/><stop offset="1" stop-color="#352044"/></linearGradient></defs><circle cx="430" cy="325" r="236" fill="none" stroke="#b9a7c5" stroke-width=".7"/><circle cx="430" cy="325" r="178" fill="none" stroke="#c8b9d2" stroke-dasharray="2 8"/><g class="weave-turn" fill="none" stroke="url(#${id}-ink)">${Array.from({length:30},(_,i)=>`<path d="M${130+i*3} ${360+i*2} C${30+i*5} ${10+i*7},${720-i*3} ${-30+i*4},${690-i*2} ${300-i*2} S${600-i*6} ${620-i*2},${160+i*3} ${390+i*2}" stroke-width="1.3"/>`).join('')}</g><g class="weave-counter" fill="none" stroke="#ef7f3b">${Array.from({length:13},(_,i)=>`<path d="M${200+i*4} 450 C${620+i*6} ${600-i*4},${790-i*3} ${190+i*5},${410-i*3} ${170+i*3}" stroke-width="1.1"/>`).join('')}</g><circle class="weave-seed" cx="575" cy="135" r="24" fill="#fdc234"/><path d="M62 565H184M62 565V541M738 74H790V126" fill="none" stroke="#9c89a8"/><text x="62" y="597" font-family="monospace" font-size="10" letter-spacing="2" fill="#796882">ESTUDO 01 / POSSIBILIDADE</text></svg>`}
function pPieces(id='pieces'){return `<svg class="p-pieces" viewBox="0 0 850 600" role="img" aria-label="Três peças geométricas se aproximam para compor uma estrutura"><defs><linearGradient id="${id}-purple"><stop stop-color="#c5aed6"/><stop offset="1" stop-color="#734b9c"/></linearGradient><filter id="${id}-shadow" x="-50%" y="-50%" width="200%" height="250%"><feGaussianBlur stdDeviation="15"/></filter></defs><ellipse cx="440" cy="455" rx="260" ry="48" fill="#523c66" opacity=".1" filter="url(#${id}-shadow)"/><g stroke="#b9a9c5" stroke-width=".7" fill="none"><path d="M90 360L480 135L780 310L390 535Z"/><path d="M100 430L650 110M170 480L720 160" stroke-dasharray="3 7"/></g><g class="piece-a"><path d="M185 280L360 180L475 247L300 348Z" fill="#ede6f1"/><path d="M185 280V322L300 390V348Z" fill="#b59ac9"/><path d="M300 348L475 247V289L300 390Z" fill="#734b9c"/><path d="M225 282L360 205L432 247L298 325Z" fill="#f6f3ee"/><path d="M225 282V295L298 338V325Z" fill="#a384ba"/></g><g class="piece-b"><path d="M395 218L560 122L680 192L515 288Z" fill="url(#${id}-purple)"/><path d="M395 218V279L515 350V288Z" fill="#734b9c"/><path d="M515 288L680 192V253L515 350Z" fill="#4c2c67"/><path d="M438 219L562 147L638 192L514 263Z" fill="#f6f3ee"/></g><g class="piece-c"><path d="M365 397L610 255L669 290L424 433Z" fill="#ffa253"/><path d="M365 397V430L424 465V433Z" fill="#e8792e"/><path d="M424 433L669 290V323L424 465Z" fill="#c45421"/></g><circle cx="735" cy="420" r="9" fill="#fdc234"/><path d="M105 510H230M105 510V490" stroke="#9a87a5"/><text x="105" y="540" font-family="monospace" font-size="10" letter-spacing="2" fill="#796882">INDEPENDÊNCIA → COMPOSIÇÃO</text></svg>`}
function pOrbits(id='orbits'){return `<svg class="p-orbits" viewBox="0 0 700 620" role="img" aria-label="Uma ação circula em limites definidos e encontra um ponto de revisão humana"><defs><radialGradient id="${id}-halo"><stop stop-color="#b494d2" stop-opacity=".13"/><stop offset="1" stop-color="#b494d2" stop-opacity="0"/></radialGradient></defs><circle cx="350" cy="310" r="285" fill="url(#${id}-halo)"/><g fill="none" stroke="#b79ecb" opacity=".65"><ellipse cx="350" cy="310" rx="250" ry="130" transform="rotate(-30 350 310)"/><ellipse cx="350" cy="310" rx="245" ry="125" transform="rotate(30 350 310)"/><ellipse cx="350" cy="310" rx="220" ry="105" transform="rotate(90 350 310)"/><circle cx="350" cy="310" r="192" stroke-dasharray="2 8"/></g><g class="orbit-move"><circle cx="350" cy="115" r="16" fill="#fdc234"/><circle cx="547" cy="307" r="7" fill="#d8bce8"/></g><g class="orbit-boundary"><path d="M238 217L350 151L464 217V405L350 470L238 405Z" fill="none" stroke="#d2b7e4"/><path d="M238 217L350 282L464 217M350 282V470" fill="none" stroke="#8c67aa"/></g><circle cx="350" cy="310" r="44" fill="#ef7f3b"/><path d="M337 310L347 320L366 299" fill="none" stroke="#2c193d" stroke-width="3"/><path d="M75 515H190M625 105H510" stroke="#b79ecb"/><text x="75" y="546" font-family="monospace" font-size="10" letter-spacing="2" fill="#c7b5d2">AUTONOMIA / COM CONTEXTO</text></svg>`}
function pPolicy(id='policy'){return `<svg class="p-policy" viewBox="0 0 1000 440" role="img" aria-label="Um percurso conecta entrada, política versionada, resultado e registro"><g stroke="#bba9c5" fill="none" stroke-width="1"><path d="M80 220H310L440 90H620L765 220H920M310 220L440 350H620L765 220"/><path d="M310 220H765" stroke-dasharray="4 8"/></g><g class="policy-lane" fill="none" stroke="#734b9c" stroke-width="2"><path d="M80 220H310L440 90H620L765 220H920"/></g><g class="policy-node pn-0"><circle cx="95" cy="220" r="38" fill="#f6f3ee" stroke="#734b9c"/><circle cx="95" cy="220" r="8" fill="#734b9c"/></g><g class="policy-node pn-1"><path d="M484 31L579 90L484 149L389 90Z" fill="#734b9c"/><path d="M484 49L549 90L484 131L419 90Z" fill="none" stroke="#ccb5dd"/><text x="484" y="96" text-anchor="middle" font-family="Inter,Arial" font-size="17" fill="#fff">v3</text></g><g class="policy-node pn-2"><circle cx="767" cy="220" r="38" fill="#ef7f3b"/><path d="M752 220L764 231L783 209" fill="none" stroke="#40244e" stroke-width="2"/></g><g class="policy-node pn-3"><rect x="880" y="185" width="64" height="70" fill="#f6f3ee" stroke="#734b9c"/><path d="M897 205H928M897 220H928M897 235H917" stroke="#734b9c"/></g><g font-family="monospace" font-size="10" letter-spacing="2" fill="#735f7f" text-anchor="middle"><text x="95" y="294">ENTRADA</text><text x="484" y="197">POLÍTICA</text><text x="484" y="392">OUTRO CAMINHO</text><text x="767" y="294">RESULTADO</text><text x="912" y="294">REGISTRO</text></g></svg>`}
function pMotionButton(){return `<button class="p-motion-control" data-motion aria-pressed="false"><span aria-hidden="true">Ⅱ</span> Pausar movimento</button>`}
function pIndex(){return `<div class="perspectives-page"><section class="journal-hero"><div class="wrap journal-hero-inner"><div>${cl('Perspectivas / Caderno de ideias')}<h1>Ideias que<br>abrem caminhos.</h1><p>Um olhar sobre as conexões entre<br>arquitetura, produto e responsabilidade.</p><a class="text-link" href="#leituras">Explore as leituras <span>↓</span></a></div><div class="journal-art">${pWeave()}</div><div class="journal-hero-bottom"><span>TECNOLOGIA TAMBÉM É UMA FORMA DE PENSAR.</span>${pMotionButton()}</div></div></section><section class="journal-library" id="leituras"><div class="wrap"><div class="journal-toolbar"><span class="label">Três ideias para explorar</span><nav aria-label="Temas de perspectivas">${[['all','Todas'],['composition','Composição'],['autonomy','Autonomia'],['decision','Decisão']].map(([k,n])=>`<button data-perspective-filter="${k}" aria-pressed="${k==='all'}">${n}</button>`).join('')}</nav></div><div id="journal-results" aria-live="polite"><article class="journal-feature" data-perspective-topic="composition"><a href="${P_URL}construir-por-composicao/" class="feature-drawing">${pPieces('index-pieces')}<span class="art-footnote">01 / A FORMA DO CONJUNTO</span></a><div class="feature-writing">${cl('Arquitetura e produto')}<h2><a href="${P_URL}construir-por-composicao/">O próximo produto<br>precisa começar<br>do zero?</a></h2><p>Uma capacidade resolve um problema inteiro. O encontro entre elas abre outras possibilidades.</p>${ca(P_URL+'construir-por-composicao/','Por que construir por composição?')}</div></article><div class="journal-secondary"><article class="journal-orbit" data-perspective-topic="autonomy"><a href="${P_URL}autonomia-responsabilidade/" class="orbit-cover">${pOrbits('index-orbits')}</a><div>${cl('Agentes e responsabilidade')}<h2><a href="${P_URL}autonomia-responsabilidade/">Onde termina<br>a autonomia?</a></h2><p>O que um agente pode fazer é tão importante quanto saber quando encaminhar.</p>${ca(P_URL+'autonomia-responsabilidade/','Explore os limites')}</div></article><article class="journal-policy" data-perspective-topic="decision"><div><span class="issue-number" aria-hidden="true">03</span>${cl('Decisão e arquitetura')}<h2><a href="${P_URL}regra-legivel/">Uma regra que<br>você consegue ler.</a></h2><p>Dados, política, resposta. Um percurso que preserva o motivo de cada decisão.</p>${ca(P_URL+'regra-legivel/','Siga o raciocínio')}</div><a href="${P_URL}regra-legivel/" class="policy-cover">${pPolicy('index-policy')}</a></article></div></div></div></section><section class="journal-end"><div class="wrap"><span class="label">Da ideia à arquitetura</span><h2>Pensar em conexões.<br>Construir com intenção.</h2>${ca('/arquitetura/','Veja como a base se organiza')}<span class="end-bracket" aria-hidden="true">↗</span></div></section></div>`}
function pBreadcrumb(title){return `<nav class="wrap breadcrumb" aria-label="Localização"><a href="/perspectivas/">Perspectivas</a><span>/</span>${title}</nav>`}
function pRelated(exclude){return `<section class="p-related"><div class="wrap"><span class="label">Outro ponto de vista</span><div>${C_ESSAYS.filter(e=>e.slug!==exclude).map(e=>`<a href="${P_URL+e.slug}/"><span>${e.tag}</span><h3>${e.title}</h3><i aria-hidden="true">↗</i></a>`).join('')}</div></div></section>`}
function pSource(slugs){return `<aside class="p-sources"><span class="label">Para aprofundar</span>${slugs.map(([u,n])=>ca(u,n)).join('')}<p>Perspectiva editorial da Catalisa. As visualizações são estudos conceituais; contratos e estágios estão na documentação de cada capacidade.</p></aside>`}
function pCompositionArticle(){return `<article class="p-article p-composition">${pBreadcrumb('Arquitetura e produto')}<header class="composition-heading wrap"><div>${cl('01 / Arquitetura e produto')}<h1>Por que construir<br>por composição?</h1><p>O contexto muda.<br>As boas responsabilidades permanecem.</p></div><div class="article-hero-art">${pPieces('article-pieces')}</div>${pMotionButton()}</header><section class="p-essay-intro wrap"><span class="essay-side-note">A FORMA DO CONJUNTO<br>UM ENSAIO SOBRE REUSO</span><p class="p-lead">Uma consulta, uma entrevista e uma reunião são experiências diferentes. As três podem precisar de uma agenda. É nesse encontro entre o que muda e o que permanece que a composição começa.</p></section><section class="p-prose wrap"><aside class="p-contents"><span class="label">Nesta leitura</span><a href="#fronteiras">Uma peça inteira</a><a href="#combinar">Combinar sem confundir</a><a href="#contextos">A mesma base</a></aside><div><section id="fronteiras"><h2>Primeiro, uma peça inteira.</h2><p>Reutilizar uma interface ou copiar uma função resolve apenas uma parte do problema. Uma capacidade precisa reunir uma responsabilidade que faça sentido: quem acessa, como um documento é guardado ou como uma política é avaliada.</p><p>Essa fronteira permite entender o que a peça recebe, o que entrega e onde termina sua atuação. Sem ela, a complexidade se desloca para as conexões e fica mais difícil descobrir quem deveria resolver cada problema.</p></section><section id="combinar"><h2>Conectar preservando as diferenças.</h2><p>A agenda conhece a disponibilidade. O canal recebe a mensagem. Uma ferramenta de IA trabalha com o contexto. O produto organiza a jornada entre essas partes.</p><p>Compor não significa que todos os blocos se tornam iguais. Significa que suas relações podem ser compreendidas e que uma mudança não precisa apagar as responsabilidades do conjunto.</p></section></div></section><section class="p-context-lab"><div class="wrap"><div class="lab-heading"><div>${cl('Explore a ideia')}<h2>A mesma capacidade.<br>Outro trabalho.</h2></div><p>Escolha um contexto para ver<br>o que muda e o que permanece.</p></div><div class="context-tabs" role="tablist" aria-label="Contextos de composição">${['Consulta','Entrevista','Reunião'].map((n,i)=>`<button role="tab" aria-selected="${i===0}" data-context="${i}">${n}</button>`).join('')}</div><div class="context-lab-body"><div class="context-architecture" data-context-visual="0">${pPieces('context-pieces')}</div><div id="context-copy" role="tabpanel" aria-live="polite">${pContextCopy(0)}</div></div><p class="lab-note">Exemplos de composição para explicar responsabilidades. Não executam integrações.</p></div></section><section class="p-closing wrap" id="contextos"><blockquote>O produto encontra<br>sua identidade.<br>A base encontra<br>novos contextos.</blockquote><div><h2>Reuso com expressão própria.</h2><p>Med, Jurídico e Recrutamento respondem a necessidades distintas. Uma conversa pode encaminhar uma consulta, reunir informações sobre um caso ou organizar uma entrevista. O domínio define a experiência e suas responsabilidades profissionais.</p><p>O que vale compartilhar é a capacidade bem delimitada. O que vale preservar é o contexto que dá sentido à jornada.</p>${pSource([['/capacidades/calendar/','Calendar'],['/capacidades/rooms/','Rooms'],['/composicoes/','Explore composições']])}</div></section>${pRelated('construir-por-composicao')}</article>`}
function pContextCopy(i){const d=[['Consulta','O profissional conduz o atendimento. A agenda encontra disponibilidade; a sala conecta a conversa.','Med mantém a liberação do registro com o profissional.'],['Entrevista','A equipe organiza o encontro com o candidato. Disponibilidade e vídeo participam de uma jornada de seleção.','O parecer depende de aprovação humana no Recrutamento.'],['Reunião','Pessoas combinam um horário e entram numa sala. O objetivo do encontro pertence a quem o organiza.','Agenda e vídeo mantêm seus contratos, independentemente do assunto.']][i];return `<span class="label">Contexto / ${d[0]}</span><h3>${d[0]}.</h3><p>${d[1]}</p><div class="shared-capabilities"><a href="/capacidades/calendar/">Calendar ↗</a><span>+</span><a href="/capacidades/rooms/">Rooms ↗</a></div><p class="context-boundary">${d[2]}</p>`}
function pAutonomyArticle(){return `<article class="p-article p-autonomy">${pBreadcrumb('Agentes e responsabilidade')}<header class="autonomy-heading"><div class="wrap"><div>${cl('02 / Agentes e responsabilidade')}<h1>Onde termina<br>a autonomia?</h1><p>Uma ferramenta amplia a ação.<br>Um limite dá sentido a ela.</p></div><div class="autonomy-hero-art">${pOrbits('article-orbits')}</div>${pMotionButton()}</div></header><section class="autonomy-opening wrap"><span class="giant-question" aria-hidden="true">?</span><div><p class="p-lead">Saber responder é diferente de poder decidir. Um agente pode reunir contexto e realizar tarefas sem assumir todas as responsabilidades da jornada.</p><p>O papel precisa ficar claro antes da ação: o que consultar, o que preparar, o que executar e em qual momento encaminhar a uma pessoa.</p></div></section><section class="agency-lab wrap"><div class="lab-heading"><div>${cl('Uma fronteira por vez')}<h2>Três verbos.<br>Responsabilidades distintas.</h2></div><p>Explore um exemplo de registro<br>no contexto do Med.</p></div><div class="agency-control" role="tablist" aria-label="Limites de atuação">${['Consultar','Preparar','Liberar'].map((n,i)=>`<button role="tab" aria-selected="${i===0}" data-agency="${i}"><span>0${i+1}</span>${n}</button>`).join('')}</div><div class="agency-panel" id="agency-panel" role="tabpanel" aria-live="polite">${pAgencyCopy(0)}</div></section><section class="autonomy-band"><div class="wrap"><span>O LIMITE FAZ PARTE DO SISTEMA.</span><h2>A aprovação humana<br>precisa ser uma etapa<br>que você consegue ver.</h2></div></section><section class="p-prose wrap"><div class="essay-side-note">INSTRUÇÃO<br>CONTEXTO<br>PERMISSÃO<br>ENCAMINHAMENTO</div><div><h2>Autonomia tem um contexto.</h2><p>Um agente que consulta disponibilidade e sugere um horário participa de uma tarefa específica. Isso não lhe dá, por consequência, autoridade para aprovar qualquer informação produzida ao longo do atendimento.</p><p>No Med, o registro preparado pela IA depende da revisão e liberação do profissional. No Jurídico, a análise do caso permanece com o advogado. No Recrutamento, o parecer exige aprovação. O desenho de cada produto precisa preservar essas diferenças.</p><h2>O encaminhamento também é trabalho.</h2><p>Encaminhar não é interromper a experiência. É conectar o próximo responsável ao contexto de que precisa: o que foi feito, o que continua em aberto e qual decisão está sendo solicitada.</p><p>Permissões e evidências ajudam a tornar essa passagem legível. A interface deve mostrar o estado do trabalho, em vez de fazer uma ação parecer concluída antes da etapa que realmente a autoriza.</p>${pSource([['/ecossistema/med/','Med'],['/ecossistema/juridico/','Jurídico'],['/ecossistema/recrutamento/','Recrutamento'],['/governanca/','Governança']])}</div></section>${pRelated('autonomia-responsabilidade')}</article>`}
function pAgencyCopy(i){const d=[['O agente encontra contexto.','Uma ferramenta pode consultar informações permitidas para apoiar o atendimento. A consulta continua sujeita ao contexto e às permissões disponíveis.','Consultas e ferramentas'],['A IA prepara um rascunho.','O conteúdo preparado ainda precisa de revisão. O produto deve deixar claro que um rascunho não equivale a um registro liberado.','Rascunho para revisão'],['O profissional revisa e libera.','A liberação do registro no Med pertence ao profissional. A etapa humana faz parte da jornada e precisa aparecer como tal.','Responsabilidade profissional']][i];return `<div class="agency-symbol state-${i}" aria-hidden="true"><svg viewBox="0 0 360 240"><circle cx="180" cy="120" r="85" fill="none" stroke="#baa5ca"/><path d="M45 120H315" stroke="#bba7c9" stroke-dasharray="3 8"/><circle class="agency-traveler" cx="${75+i*105}" cy="120" r="27" fill="${i===2?'#ef7f3b':'#734b9c'}"/><path d="M${65+i*105} 120L${73+i*105} 128L${87+i*105} 112" stroke="#f6f3ee" fill="none" stroke-width="2"/></svg><span>${d[2]}</span></div><div><h3>${d[0]}</h3><p>${d[1]}</p></div>`}
function pRuleArticle(){return `<article class="p-article p-rule">${pBreadcrumb('Decisão e arquitetura')}<header class="rule-heading wrap">${cl('03 / Decisão e arquitetura')}<h1>Uma regra<br>que você<br>consegue <em>ler.</em></h1><div class="rule-margin"><span class="rule-version">v3</span><p>Uma política tem uma versão.<br>Uma resposta tem um percurso.</p><a href="#percurso" class="text-link">Siga uma decisão <span>↓</span></a></div></header><section class="policy-playground" id="percurso"><div class="wrap"><div class="policy-track" data-step="0">${pPolicy('article-policy')}</div><div class="policy-controls"><div class="policy-step-select" role="tablist" aria-label="Percurso de uma decisão">${['Entrada','Política','Resultado','Registro'].map((n,i)=>`<button role="tab" aria-selected="${i===0}" data-policy-step="${i}"><span>0${i+1}</span>${n}</button>`).join('')}</div><div id="policy-description" role="tabpanel" aria-live="polite">${pPolicyCopy(0)}</div></div><p class="lab-note">Percurso ilustrativo. “v3” é uma versão fictícia para explicar o conceito; não executa uma política real.</p></div></section><section class="rule-opening wrap"><h2>O resultado<br>é só uma parte<br>da resposta.</h2><p class="p-lead">Quando uma regra muda, a próxima execução pode ter outro comportamento. Entender qual política participou da decisão é tão importante quanto conhecer o resultado.</p></section><section class="rule-comparison wrap"><div><span class="label">Decisão</span><h3>O motor avalia.</h3><p>Decision Engine executa regras em tabelas DMN publicadas e versionadas. A política pertence a esse contrato.</p>${ca('/capacidades/decision-engine/','Explore o motor')}</div><span class="comparison-join" aria-hidden="true">↔</span><div><span class="label">Orquestração</span><h3>A esteira organiza.</h3><p>Decision Platform reúne fontes e coordena o percurso até a resposta. Buscar dados e avaliar uma política são trabalhos distintos.</p>${ca('/capacidades/decision-platform/','Explore a esteira')}</div></section><section class="p-prose wrap"><div class="essay-side-note">CONTRATOS DIFERENTES.<br>UM PERCURSO LEGÍVEL.</div><div><h2>Uma fronteira que ajuda a mudar.</h2><p>Se a integração de uma fonte e o conteúdo de uma regra estiverem misturados, uma mudança localizada pode exigir rever o processo inteiro. Separar essas responsabilidades permite discutir cada parte com mais precisão.</p><p>O fluxo precisa saber como obter os dados e como continuar a jornada. A política precisa explicar como aqueles dados participam da avaliação. A versão liga a execução à regra que estava publicada naquele momento.</p><h2>Legibilidade é uma decisão de arquitetura.</h2><p>Uma regra legível não substitui o conhecimento de domínio. Ela permite que esse conhecimento seja discutido, revisado e localizado. A interface ajuda quando mostra a política e o estado da execução sem esconder as fronteiras entre as capacidades.</p>${pSource([['/capacidades/decision-engine/','Decision Engine'],['/capacidades/decision-platform/','Decision Platform'],['/ecossistema/decision/','Decision no ecossistema']])}</div></section>${pRelated('regra-legivel')}</article>`}
function pPolicyCopy(i){return `<h3>${['O contexto entra na jornada.','A política publicada é avaliada.','A execução produz uma resposta.','O percurso preserva sua referência.'][i]}</h3><p>${['Os dados necessários pertencem ao contrato e ao contexto da composição.','A versão identifica qual conjunto de regras participa da execução.','A resposta precisa ser compreendida no escopo da política que a produziu.','Versão e contexto ajudam a explicar o que orientou aquela execução.'][i]}</p>`}
const pOriginalPage=cPage;
cPage=function(route,blocks){if(route==='/perspectivas/')return pIndex();return pOriginalPage(route,blocks)};
cArticle=function(e){return e.slug==='construir-por-composicao'?pCompositionArticle():e.slug==='autonomia-responsabilidade'?pAutonomyArticle():pRuleArticle()};
function pBind(){const root=document.querySelector('.perspectives-page,.p-article');if(!root)return;document.querySelectorAll('[data-perspective-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-perspective-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('[data-perspective-topic]').forEach(a=>a.hidden=b.dataset.perspectiveFilter!=='all'&&a.dataset.perspectiveTopic!==b.dataset.perspectiveFilter);document.querySelector('.journal-secondary')?.classList.toggle('single-result',b.dataset.perspectiveFilter!=='all')}));function bindTabs(selector,act){const tabs=[...document.querySelectorAll(selector)];tabs.forEach((b,i)=>{b.addEventListener('click',()=>{tabs.forEach(x=>x.setAttribute('aria-selected',String(x===b)));act(i)});b.addEventListener('keydown',e=>{if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[n].focus();tabs[n].click()}})})}bindTabs('[data-context]',i=>{document.getElementById('context-copy').innerHTML=pContextCopy(i);document.querySelector('[data-context-visual]').dataset.contextVisual=String(i)});bindTabs('[data-agency]',i=>document.getElementById('agency-panel').innerHTML=pAgencyCopy(i));bindTabs('[data-policy-step]',i=>{document.querySelector('.policy-track').dataset.step=String(i);document.getElementById('policy-description').innerHTML=pPolicyCopy(i)});document.querySelectorAll('[data-motion]').forEach(b=>b.addEventListener('click',()=>{const paused=root.classList.toggle('motion-paused');b.setAttribute('aria-pressed',String(paused));b.innerHTML=paused?'<span aria-hidden="true">▶</span> Retomar movimento':'<span aria-hidden="true">Ⅱ</span> Pausar movimento'}));if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const obs=new IntersectionObserver(es=>es.forEach(e=>{e.target.classList.toggle('art-in-view',e.isIntersecting)}),{threshold:.1});document.querySelectorAll('.journal-feature,.orbit-cover,.article-hero-art').forEach(el=>obs.observe(el))}}
if(typeof document!=='undefined'&&document.addEventListener)document.addEventListener('DOMContentLoaded',pBind);
